pragma solidity ^0.8.20;

contract Vault {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function withdraw(uint256 amount) public onlyOwner {
        payable(owner).transfer(amount);
    }
}

mapping(address => uint256) public balanceOf;
event Transfer(address indexed from, address indexed to, uint256 value);

function transfer(address to, uint256 amount) public returns (bool) {
    require(balanceOf[msg.sender] >= amount, "Insufficient balance");
    balanceOf[msg.sender] -= amount;
    balanceOf[to] += amount;
    emit Transfer(msg.sender, to, amount);
    return true;
}

struct Listing {
    address seller;
    uint256 price;
    bool active;
}

mapping(uint256 => Listing) public listings;
uint256 public nextListingId;

function createListing(uint256 price) public returns (uint256) {
    uint256 id = nextListingId;
    listings[id] = Listing({ seller: msg.sender, price: price, active: true });
    nextListingId++;
    return id;
}

event ListingSold(uint256 indexed listingId, address indexed seller, address indexed buyer);

function buy(uint256 listingId) public payable {
    Listing storage listing = listings[listingId];
    require(listing.active, "Not active");
    require(msg.value >= listing.price, "Insufficient payment");

    listing.active = false;
    payable(listing.seller).transfer(msg.value);

    emit ListingSold(listingId, listing.seller, msg.sender);
}

